{
  "lecture": [
    {
      "etiquette": "F11",
      "R1": {
        "valeur": 1,
        "passage": "À tirages frais totaux égaux, la part des composantes plantées portées par au moins une carte soumise et couvertes au sens de l'oracle augmente d'au moins 20 % en relatif"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois après chaque course : composantes couvertes, lois fausses et copies promues, aux trois étages (propositions brutes, représentants, retenues)."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le gain de puissance est obtenu sans toucher au nul, sans signal servi à un agent et avec une garantie démontrable sous arrêt optionnel."
      },
      "R4": {
        "valeur": 1,
        "passage": "La garantie est conservée : une valeur e arrêtée à un temps d'arrêt garde une espérance au plus 1 sous le nul."
      },
      "R5": {
        "valeur": 1,
        "passage": "4. Arrêt bas : la valeur e passe sous 1/20, après au moins un quart de la part fixe du témoin. 5. Arrêt haut : la valeur e atteint m/α, avec m fixé d'avance par règle écrite."
      },
      "R6": {
        "valeur": 1,
        "passage": "Quelques heures de processeur : mondes et cartes synthétiques écrits par programme, puis rejeu des cartes déjà jouées. Aucun appel de modèle."
      },
      "R7": {
        "valeur": 1,
        "passage": "Les tirages libérés par les groupes arrêtés tôt vont aux groupes encore actifs, ce qui fait franchir le seuil à des composantes proches de la détectabilité."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F12",
      "R1": {
        "valeur": 1,
        "passage": "le bras stratifié couvre au niveau des retenues au moins 1,5 fois plus de composantes rares que le bras à tirages uniformes (seuil : ≥ +50 % sur la somme des 20 mondes)"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, par strate de masse, à l'étage des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "e-BH inchangé ; le test de mort reçoit la même stratification. Aucune information sur la stratification n'est servie aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "la loi de tirage des traits est libre tant qu'elle est indépendante des cartes, donc la garantie E[e] ≤ 1 sous le nul est conservée sans aucune correction"
      },
      "R5": {
        "valeur": 0,
        "motif": "La répartition des effectifs entre strates est renvoyée à une règle future, avec seulement un exemple, sans fixer l'allocation à programmer."
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues sur mondes générés par programme ; quelques heures de calcul local, zéro appel."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un laboratoire mieux doté augmente le nombre de tirages ; cela ne lève pas la borne de dilution (une région de masse r(A) reçoit r(A) fois les tirages)."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F13",
      "R1": {
        "valeur": 1,
        "passage": "à coût en dollars et en jetons strictement égal, le nombre de composantes plantées vraies couvertes au sens de l'oracle dans les retenues augmente d'au moins 25 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "chacun en session neuve sans historique, recevant exactement la même vue publique complète (sans aucun masquage de l'archive) et la consigne de rendre exactement 1 carte."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "fixer le plafond de jetons de sortie de chaque appel unitaire à floor((J - 5 * P * r) / 6), où r est le ratio tarifaire entre un jeton d'entrée et un jeton de sortie du modèle considéré."
      },
      "R6": {
        "valeur": 1,
        "passage": "(quelques dizaines de dollars d'appels) et à comparer par l'oracle la couverture des 6 appels d'une carte contre 1 appel de 6 cartes à budget de dollars strictement égal."
      },
      "R7": {
        "valeur": 1,
        "passage": "Élimine à la source la corrélation autorégressive entre les six cartes d'un même proposeur au sein d'un appel, empêchant la première carte générée d'agir comme un attracteur pour les cinq suivantes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F14",
      "R1": {
        "valeur": 1,
        "passage": "la part des réécritures adoptées qui battent vraiment la consigne précédente sur des mondes frais du vivier au moins doublée par rapport à la règle \" garder si le score a monté \""
      },
      "R2": {
        "valeur": 1,
        "passage": "réécritures adoptées qui ne battent pas la consigne précédente sur des mondes frais du vivier (oracle) ; composantes plantées couvertes sur la famille jamais vue (oracle)"
      },
      "R3": {
        "valeur": 1,
        "passage": "L'oracle du vivier de conception donne une différence vraie à chaque monde : l'e-processus parie sur une quantité exacte, sans note de juge"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "met à jour la richesse W ← W·(1 + λ·d) avec λ = 0,5 ; adoption dès que W ≥ 20 (niveau 0,05 par décision) ; abandon au plus après 40 mondes ; rien n'est adopté sans franchissement."
      },
      "R6": {
        "valeur": 1,
        "passage": "rejouable sur les journaux de conception déjà écrits, environ 6 heures de processeur ; si les journaux manquent, quelques mondes neufs, de l'ordre de 30 USD"
      },
      "R7": {
        "valeur": 1,
        "passage": "Elle n'est adoptée que lorsqu'un e-processus par paris accumule une preuve décisive. On peut arrêter tôt, et la probabilité de fausse adoption reste bornée par décision, même sous arrêt optionnel."
      },
      "N": {
        "valeur": "C7",
        "passage_fiche": "Chaque réécriture candidate est comparée à la consigne en place sur les mêmes mondes du vivier. Elle n'est adoptée que lorsqu'un e-processus par paris accumule une preuve décisive.",
        "passage_catalogue": "chaque candidate est comparée à la version en place **sur les mêmes instances**, et adoptée seulement quand un **e-processus par paris** accumule une preuve décisive"
      }
    },
    {
      "etiquette": "F15",
      "R1": {
        "valeur": 1,
        "passage": "composantes rares couvertes aux retenues au moins 2 fois celles du bras sans lentille sur la somme des 12 mondes (et au moins +3 en valeur absolue)"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par strate de masse, aux étages des propositions brutes, des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "les réutiliser côté proposeurs ne masque rien de l'archive (rejet établi : aucun masquage), n'impose aucun quota de formes et n'ajoute aucune prime"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "Avant la génération, un programme de l'orchestrateur tire, à graine scellée, une permutation des S strates publiques et attribue une strate à chaque proposeur"
      },
      "R6": {
        "valeur": 1,
        "passage": "12 mondes × 2 bras × 4 proposeurs × 1 appel ; ordre de quelques dizaines de dollars ; devis avant feu vert."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un acteur qui ajoute des modèles de frontière sans partition recouvre le même bassin global ; la partition par strates publiques scellée est une propriété de la composition de l'organisme"
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
